const updateMaintenancePlan = `-- name: UpdateMaintenancePlan :one
UPDATE maintenance_plans SET title = $2, interval_hours = $3, interval_months = $4,
    next_due_hours = $5, next_due_date = $6, quarantine_when_due = $7, active = $8
WHERE plan_id = $1 RETURNING plan_id, asset_id, component_id, title, interval_hours, interval_months, next_due_hours, next_due_date, quarantine_when_due, active
`

type UpdateMaintenancePlanParams struct {
	PlanID            uuid.UUID   `json:"plan_id"`
	Title             string      `json:"title"`
	IntervalHours     *int64      `json:"interval_hours"`
	IntervalMonths    *int32      `json:"interval_months"`
	NextDueHours      *int64      `json:"next_due_hours"`
	NextDueDate       pgtype.Date `json:"next_due_date"`
	QuarantineWhenDue bool        `json:"quarantine_when_due"`
	Active            bool        `json:"active"`
}

func (q *Queries) UpdateMaintenancePlan(ctx context.Context, arg UpdateMaintenancePlanParams) (MaintenancePlan, error) {
	row := q.db.QueryRow(ctx, updateMaintenancePlan,
		arg.PlanID,
		arg.Title,
		arg.IntervalHours,
		arg.IntervalMonths,
		arg.NextDueHours,
		arg.NextDueDate,
		arg.QuarantineWhenDue,
		arg.Active,
	)
	var i MaintenancePlan
	err := row.Scan(
		&i.PlanID,
		&i.AssetID,
		&i.ComponentID,
		&i.Title,
		&i.IntervalHours,
		&i.IntervalMonths,
		&i.NextDueHours,
		&i.NextDueDate,
		&i.QuarantineWhenDue,
		&i.Active,
	)
	return i, err
}
